function solve(linha) {
  const result = [];
  let i = 0;
  let current = '';
  let inQuotes = false;

  while (i < linha.length) {
    const ch = linha[i];

    if (ch === '"') {
      if (i + 1 < linha.length && linha[i + 1] === '"') {
        // Dois aspas consecutivas -> aspas literais
        current += '"';
        i += 2;
      } else {
        // Fim de aspas
        inQuotes = false;
        i++;
      }
    } else if (ch === '"' && inQuotes) {
      // Aspa simples dentro de aspas = terminador de aspas
      current += '"';
      i++;
    } else if (ch === ',' && !inQuotes) {
      // Vírgula fora de aspas -> fim de campo
      result.push(current);
      current = '';
      i++;
    } else {
      // Qualquer outro caractere
      current += ch;
      i++;
    }
  }

  // Último campo
  result.push(current);

  return result;
}
