function solve(a, b) {
  // Parse SemVer 2.0.0 (pre-release only, no build metadata)
  function parse(v) {
    const match = v.match(/^(\d+)\.(\d+)\.(\d+)(?:-([a-zA-Z0-9.]*))?(?:\+[^+]*)?$/);
    if (!match) throw new Error('Invalid semver');
    return {
      major: +match[1],
      minor: +match[2],
      patch: +match[3],
      pre: match[4] || null
    };
  }

  const x = parse(a), y = parse(b);
  const cmp = (a, b) => {
    if (a.major !== b.major) return a.major - b.major;
    if (a.minor !== b.minor) return a.minor - b.minor;
    if (a.patch !== b.patch) return a.patch - b.patch;
    // Pre-release: if both have it, compare identifiers; if only one has it, it's lower
    if (x.pre !== null && y.pre === null) return -1;
    if (x.pre === null && y.pre !== null) return 1;
    if (!x.pre && !y.pre) return 0;
    const parts = x.pre.split('.');
    for (const p of parts) {
      const pa = p.split('-')[0];
      const pb = p.split('-')[1] || '';
      const na = +pa || 0;
      const nb = +pb || 0;
      if (na !== nb) return na - nb;
    }
    return 0;
  };

  return cmp(x, y);
}
