function solve(a, b) {
  const parse = (v) => {
    const parts = v.split('+')[0];
    const split = parts.split('-');
    const release = split[0].split('.').map(Number);
    const prerelease = split.length > 1 ? split[1].split('.') : null;
    return { release, prerelease };
  };

  const p1 = parse(a);
  const p2 = parse(b);

  for (let i = 0; i < 3; i++) {
    if (p1.release[i] !== p2.release[i]) {
      return p1.release[i] > p2.release[i] ? 1 : -1;
    }
  }

  if (p1.prerelease !== null && p2.prerelease !== null) {
    const len = Math.max(p1.prerelease.length, p2.prerelease.length);
    for (let i = 0; i < len; i++) {
      const id1 = p1.prerelease[i];
      const id2 = p2.prerelease[i];
      if (id1 === undefined && id2 === undefined) continue;
      if (id1 === undefined) return -1;
      if (id2 === undefined) return 1;
      const num1 = Number(id1);
      const num2 = Number(id2);
      if (!isNaN(num1) && !isNaN(num2)) {
        if (num1 !== num2) return num1 > num2 ? 1 : -1;
      } else {
        if (id1 !== id2) return id1 < id2 ? -1 : 1;
      }
    }
    return 0;
  }

  if (p1.prerelease === null && p2.prerelease === null) {
    return 0;
