function solve(a, b) {
  const parse = (v) => {
    const [core, pre] = v.split('-');
    const [major, minor, patch] = core.split('.').map(Number);
    return { major, minor, patch, pre };
  };

  const cmpNum = (x, y) => (x < y ? -1 : x > y ? 1 : 0);
  const cmpPre = (pa, pb) => {
    if (!pa && !pb) return 0;
    if (!pa) return 1;
    if (!pb) return -1;
    const partsA = pa.split('.');
    const partsB = pb.split('.');
    for (let i = 0; i < Math.max(partsA.length, partsB.length); i++) {
      const a = partsA[i];
      const b = partsB[i];
      if (a === undefined) return -1;
      if (b === undefined) return 1;
      const an = Number(a);
      const bn = Number(b);
      const aIsNum = !Number.isNaN(an);
      const bIsNum = !Number.isNaN(bn);
      if (aIsNum && !bIsNum) return -1;
      if (!aIsNum && bIsNum) return 1;
      if (aIsNum && bIsNum) {
        const c = cmpNum(an, bn);
        if (c !== 0) return c;
      } else {
        const c = a.localeCompare(b, 'en');
        if (c !== 0) return c;
      }
    }
    return 0;
  };

  const A = parse(a);
  const B = parse(b);

  for (const k of ['major', 'minor', 'patch']) {
    const c = cmpNum(A[k], B[k]);
    if (c !== 0) return c;
  }

  return cmpPre(A.pre, B.pre);
}
