function solve(a, b) {
  function parse(s) {
    const [main, pre] = s.split('-');
    const [major, minor, patch] = main.split('.').map(Number);
    return { major, minor, patch, pre };
  }

  function comparePrerelease(a, b) {
    if (!a && !b) return 0;
    if (!a) return -1;
    if (!b) return 1;
    const pa = a.split('.');
    const pb = b.split('.');
    const len = Math.max(pa.length, pb.length);
    for (let i = 0; i < len; i++) {
      const x = pa[i] || '';
      const y = pb[i] || '';
      const nx = x.split('-').map(Number);
      const ny = y.split('-').map(Number);
      if (nx.length > 0 && ny.length === 0) return -1;
      if (nx.length === 0 && ny.length > 0) return 1;
      if (nx.length > 0 && ny.length > 0) {
        const mn = Math.min(nx[0], ny[0]);
        if (mn < nx[0]) return -1;
        if (mn > ny[0]) return 1;
      }
      if (x < y) return -1;
      if (x > y) return 1;
    }
    return 0;
  }

  const a1 = parse(a);
  const b1 = parse(b);

  if (a1.major !== b1.major) return a1.major - b1.major;
  if (a1.minor !== b1.minor) return a1.minor - b1.minor;
  if (a1.patch !== b1.patch) return a1.patch - b1.patch;

  if (a1.pre && b1.pre) {
    const cmp = comparePrerelease(a1.pre, b1.pre);
    if (cmp !== 0) return cmp;
    return 0;
  }
  if (a1.pre) return -1;
  if (b1.pre) return 1;

  return 0;
}
