    max = Math.max(max, precos[i]);
    backward[i] = Math.max(backward[i + 1] || 0, max - precos[i]);
  }

  let maxProfit = 0;
  for (let i = 0; i < n; i++) {
    maxProfit = Math.max(maxProfit, forward[i] + backward[i]);
  }

  return maxProfit;
}
